///|
/// Reverse-mode scalar node. A tape owns nodes; never mix values from tapes.
pub struct Value {
  id : Int32
  value : Double
} derive(Debug)

///|
struct Node {
  left : Int32
  right : Int32
  dl : Double
  dr : Double
  mut gradient : Double
}

///|
/// A fresh tape per minibatch releases the entire unrolled computation graph.
pub struct Tape {
  priv nodes : Array[Node]
}

///|
pub fn Tape::new() -> Tape {
  { nodes: [], }
}

///|
pub fn Tape::scalar(self : Tape, value : Double) -> Value {
  self.node(value, -1, -1, 0, 0)
}

///|
fn Tape::node(
  self : Tape,
  value : Double,
  left : Int32,
  right : Int32,
  dl : Double,
  dr : Double,
) -> Value {
  let id = self.nodes.length()
  self.nodes.push({ left, right, dl, dr, gradient: 0, })
  { id, value, }
}

///|
pub fn Tape::add(self : Tape, a : Value, b : Value) -> Value {
  self.node(a.value + b.value, a.id, b.id, 1, 1)
}

///|
pub fn Tape::sub(self : Tape, a : Value, b : Value) -> Value {
  self.node(a.value - b.value, a.id, b.id, 1, -1)
}

///|
pub fn Tape::mul(self : Tape, a : Value, b : Value) -> Value {
  self.node(a.value * b.value, a.id, b.id, b.value, a.value)
}

///|
pub fn Tape::div(self : Tape, a : Value, b : Value) -> Value {
  self.node(
    a.value / b.value,
    a.id,
    b.id,
    1 / b.value,
    -a.value / (b.value * b.value),
  )
}

///|
pub fn Tape::scale(self : Tape, a : Value, factor : Double) -> Value {
  self.node(a.value * factor, a.id, -1, factor, 0)
}

///|
pub fn Tape::exp(self : Tape, a : Value) -> Value {
  let value = @math.exp(a.value)
  self.node(value, a.id, -1, value, 0)
}

///|
pub fn Tape::log(self : Tape, a : Value) -> Value {
  self.node(@math.ln(a.value), a.id, -1, 1 / a.value, 0)
}

///|
pub fn Tape::sqrt(self : Tape, a : Value) -> Value {
  let value = a.value.sqrt()
  self.node(value, a.id, -1, 0.5 / value, 0)
}

///|
pub fn Tape::tanh(self : Tape, a : Value) -> Value {
  let value = @math.tanh(a.value)
  self.node(value, a.id, -1, 1 - value * value, 0)
}

///|
pub fn Tape::sigmoid(self : Tape, a : Value) -> Value {
  let value = if a.value >= 0 {
    1.0 / (1.0 + @math.exp(-a.value))
  } else {
    let e = @math.exp(a.value)
    e / (1.0 + e)
  }
  self.node(value, a.id, -1, value * (1 - value), 0)
}

///|
pub fn Tape::silu(self : Tape, a : Value) -> Value {
  self.mul(a, self.sigmoid(a))
}

///|
/// Piecewise clamp, including PyTorch's derivative at the bounds.
pub fn Tape::clamp(
  self : Tape,
  a : Value,
  lower : Double,
  upper : Double,
) -> Value {
  if a.value < lower {
    self.scalar(lower)
  } else if a.value > upper {
    self.scalar(upper)
  } else {
    a
  }
}

///|
pub fn Tape::minimum(self : Tape, a : Value, b : Value) -> Value {
  if a.value < b.value {
    a
  } else if a.value > b.value {
    b
  } else {
    self.scale(self.add(a, b), 0.5)
  }
}

///|
pub fn Tape::maximum(self : Tape, a : Value, b : Value) -> Value {
  if a.value > b.value {
    a
  } else if a.value < b.value {
    b
  } else {
    self.scale(self.add(a, b), 0.5)
  }
}

///|
pub fn Tape::backward(self : Tape, output : Value) -> Unit {
  for node in self.nodes {
    node.gradient = 0
  }
  self.nodes[output.id].gradient = 1
  for i = self.nodes.length() - 1; i >= 0; i = i - 1 {
    let node = self.nodes[i]
    if node.gradient == 0 {
      continue
    }
    if node.left >= 0 {
      self.nodes[node.left].gradient += node.gradient * node.dl
    }
    if node.right >= 0 {
      self.nodes[node.right].gradient += node.gradient * node.dr
    }
  }
}

///|
pub fn Tape::gradient(self : Tape, input : Value) -> Double {
  self.nodes[input.id].gradient
}

///|
pub fn Tape::sin(self : Tape, input : Value) -> Value {
  self.node(@math.sin(input.value), input.id, -1, @math.cos(input.value), 0)
}

///|
pub fn Tape::cos(self : Tape, input : Value) -> Value {
  self.node(@math.cos(input.value), input.id, -1, -@math.sin(input.value), 0)
}

///|
pub fn Tape::atan2(self : Tape, y : Value, x : Value) -> Value {
  let norm2 = x.value * x.value + y.value * y.value
  self.node(
    @math.atan2(y.value, x.value),
    y.id,
    x.id,
    x.value / norm2,
    -y.value / norm2,
  )
}

///|
pub fn Tape::acos(self : Tape, input : Value) -> Value {
  self.node(
    @math.acos(input.value),
    input.id,
    -1,
    -1.0 / (1.0 - input.value * input.value).sqrt(),
    0,
  )
}

///|
pub fn Tape::abs(self : Tape, input : Value) -> Value {
  self.node(
    input.value.abs(),
    input.id,
    -1,
    if input.value > 0 {
      1
    } else if input.value < 0 {
      -1
    } else {
      0
    },
    0,
  )
}

///|
pub fn Tape::vector(self : Tape, values : Array[Double]) -> Array[Value] {
  values.map(x => self.scalar(x))
}

///|
pub fn Tape::mean(self : Tape, values : Array[Value]) -> Value {
  guard values.length() > 0 else { abort("mean requires nonempty input") }
  let mut total = self.scalar(0)
  for v in values {
    total = self.add(total, v)
  }
  self.scale(total, 1.0 / values.length().to_double())
}

///|
/// Portable RNG, intentionally distinct from Torch RNG.
pub struct Rng {
  priv mut state : UInt32
} derive(Debug)

///|
pub fn Rng::new(seed : UInt32) -> Rng {
  let initial = seed ^ 0x9E3779B9U
  { state: if initial == 0 { 1U } else { initial }, }
}

///|
pub fn Rng::state(self : Rng) -> UInt32 {
  self.state
}

///|
pub fn Rng::snapshot(self : Rng) -> Rng {
  { state: self.state, }
}

///|
pub fn Rng::set_state(self : Rng, state : UInt32) -> Unit {
  guard state != 0 else { abort("xorshift state must be nonzero") }
  self.state = state
}

///|
pub fn Rng::uniform(self : Rng) -> Double {
  let mut x = self.state
  x = x ^ (x << 13)
  x = x ^ (x >> 17)
  x = x ^ (x << 5)
  self.state = x
  (x.to_double() + 0.5) / 4294967296.0
}

///|
pub fn Rng::index(self : Rng, length : Int32) -> Int32 {
  guard length > 0 else { abort("empty sampling pool") }
  (self.uniform() * length.to_double()).to_int()
}

///|
pub fn Rng::normal(self : Rng) -> Double {
  (-2.0 * @math.ln(self.uniform())).sqrt() *
  @math.cos(6.283185307179586 * self.uniform())
}

///|
pub fn[T] Rng::shuffle(self : Rng, values : Array[T]) -> Unit {
  for i = values.length() - 1; i > 0; i = i - 1 {
    let j = self.index(i + 1)
    let saved = values[i]
    values[i] = values[j]
    values[j] = saved
  }
}

///|
/// SiLU hidden layers, row-major [output,input] weights followed by biases.
pub(all) struct MLP {
  dimensions : Array[Int32]
  parameters : Array[Double]
} derive(Debug)

///|
pub fn MLP::new(
  dimensions : Array[Int32],
  rng : Rng,
  zero_last~ : Bool = false,
) -> MLP {
  guard dimensions.length() >= 2 && dimensions.all(n => n > 0) else {
    abort("invalid MLP dimensions")
  }
  let parameters = []
  for layer in 0..<(dimensions.length() - 1) {
    let nin = dimensions[layer]
    let nout = dimensions[layer + 1]
    let bound = 1.0 / nin.to_double().sqrt()
    let zero = zero_last && layer == dimensions.length() - 2
    for _ in 0..<(nin * nout + nout) {
      parameters.push(
        if zero {
          0.0
        } else {
          (2.0 * rng.uniform() - 1) * bound
        },
      )
    }
  }
  { dimensions: dimensions.copy(), parameters, }
}

///|
pub fn MLP::bind(self : MLP, tape : Tape) -> Array[Value] {
  tape.vector(self.parameters)
}

///|
pub fn MLP::forward(
  self : MLP,
  tape : Tape,
  parameters : Array[Value],
  inputs : Array[Value],
) -> Array[Value] {
  guard inputs.length() == self.dimensions[0] &&
    parameters.length() == self.parameters.length() else {
    abort("MLP shape mismatch")
  }
  let mut values = inputs
  let mut offset = 0
  for layer in 0..<(self.dimensions.length() - 1) {
    let nin = self.dimensions[layer]
    let nout = self.dimensions[layer + 1]
    let next = Array::makei(nout, row => {
      let mut sum = parameters[offset + nin * nout + row]
      for column in 0..<nin {
        sum = tape.add(
          sum,
          tape.mul(parameters[offset + row * nin + column], values[column]),
        )
      }
      if layer < self.dimensions.length() - 2 {
        tape.silu(sum)
      } else {
        sum
      }
    })
    offset += nin * nout + nout
    values = next
  }
  values
}

///|
pub fn MLP::predict(self : MLP, inputs : Array[Double]) -> Array[Double] {
  let tape = Tape::new()
  self.forward(tape, self.bind(tape), tape.vector(inputs)).map(v => v.value)
}

///|
pub fn MLP::snapshot(self : MLP) -> MLP {
  { dimensions: self.dimensions.copy(), parameters: self.parameters.copy(), }
}

///|
pub(all) struct Normalization {
  mean : Array[Double]
  scale : Array[Double]
} derive(Debug)

///|
pub fn finite(value : Double) -> Bool {
  value == value && value - value == 0
}

///|
pub fn fit_normalization(
  rows : Array[Array[Double]],
  floor : Double,
) -> Normalization {
  guard rows.length() > 0 && floor > 0 else {
    abort("normalization requires data and positive floor")
  }
  let width = rows[0].length()
  let mean = Array::make(width, 0.0)
  let variance = Array::make(width, 0.0)
  for row in rows {
    guard row.length() == width else { abort("ragged normalization data") }
    for j in 0..<width {
      mean[j] += row[j] / rows.length().to_double()
    }
  }
  for row in rows {
    for j in 0..<width {
      let delta = row[j] - mean[j]
      variance[j] += delta * delta / rows.length().to_double()
    }
  }
  { mean, scale: variance.map(v => @math.maximum(v.sqrt(), floor)), }
}

///|
pub fn Normalization::apply(
  self : Normalization,
  tape : Tape,
  inputs : Array[Value],
) -> Array[Value] {
  guard inputs.length() == self.mean.length() else {
    abort("normalization shape mismatch")
  }
  Array::makei(inputs.length(), i => {
    tape.scale(
      tape.sub(inputs[i], tape.scalar(self.mean[i])),
      1 / self.scale[i],
    )
  })
}

///|
/// Persistent Adam moments and bias-correction step.
pub struct Adam {
  first : Array[Double]
  second : Array[Double]
  mut steps : Int32
  mut learning_rate : Double
  beta1 : Double
  beta2 : Double
  epsilon : Double
} derive(ToJson, FromJson)

///|
pub fn Adam::new(
  count : Int32,
  learning_rate : Double,
  beta1~ : Double = 0.9,
  beta2~ : Double = 0.999,
  epsilon~ : Double = 0.00000001,
) -> Adam {
  guard count >= 0 &&
    finite(learning_rate) &&
    learning_rate >= 0 &&
    beta1 >= 0 &&
    beta1 < 1 &&
    beta2 >= 0 &&
    beta2 < 1 &&
    epsilon > 0 &&
    finite(epsilon) else {
    abort("invalid Adam configuration")
  }
  {
    first: Array::make(count, 0.0),
    second: Array::make(count, 0.0),
    steps: 0,
    learning_rate,
    beta1,
    beta2,
    epsilon,
  }
}

///|
/// Return pre-clipping norm, update only explicitly supplied parameters.
pub fn Adam::step(
  self : Adam,
  parameters : Array[Double],
  tape : Tape,
  bound : Array[Value],
  max_norm~ : Double = 1.0,
  max_value~ : Double = 1.0 / 0.0,
) -> Double {
  guard parameters.length() == self.first.length() &&
    bound.length() == parameters.length() else {
    abort("Adam shape mismatch")
  }
  let gradient = bound.map(v => tape.gradient(v))
  let mut sum = 0.0
  for g in gradient {
    guard finite(g) else { abort("nonfinite gradient") }
    sum += g * g
  }
  let norm = sum.sqrt()
  guard finite(norm) && max_norm >= 0 && max_value >= 0 else {
    abort("nonfinite gradient norm or invalid clipping bound")
  }
  let coefficient = @math.minimum(1.0, max_norm / (norm + 0.000001))
  self.steps += 1
  let correction1 = 1.0 - @math.pow(self.beta1, self.steps.to_double())
  let correction2 = 1.0 - @math.pow(self.beta2, self.steps.to_double())
  for i in 0..<parameters.length() {
    let raw = gradient[i] * coefficient
    let g = if raw > max_value {
      max_value
    } else if raw < -max_value {
      -max_value
    } else {
      raw
    }
    self.first[i] = self.beta1 * self.first[i] + (1 - self.beta1) * g
    self.second[i] = self.beta2 * self.second[i] + (1 - self.beta2) * g * g
    parameters[i] -= self.learning_rate *
      (self.first[i] / correction1) /
      ((self.second[i] / correction2).sqrt() + self.epsilon)
  }
  norm
}

///|
pub fn Adam::set_learning_rate(self : Adam, learning_rate : Double) -> Unit {
  guard learning_rate >= 0 && finite(learning_rate) else {
    abort("invalid Adam learning rate")
  }
  self.learning_rate = learning_rate
}

///|
pub fn Adam::snapshot(self : Adam) -> Adam {
  {
    first: self.first.copy(),
    second: self.second.copy(),
    steps: self.steps,
    learning_rate: self.learning_rate,
    beta1: self.beta1,
    beta2: self.beta2,
    epsilon: self.epsilon,
  }
}

///|
pub fn Adam::restore(self : Adam, saved : Adam) -> Unit {
  guard self.first.length() == saved.first.length() &&
    self.beta1 == saved.beta1 &&
    self.beta2 == saved.beta2 &&
    self.epsilon == saved.epsilon else {
    abort("incompatible Adam state")
  }
  for i in 0..<self.first.length() {
    self.first[i] = saved.first[i]
    self.second[i] = saved.second[i]
  }
  self.steps = saved.steps
  self.learning_rate = saved.learning_rate
}

///|
test "reverse tape differentiates shared branches and resets accumulated gradients" {
  let tape = @numeric.Tape::new()
  let x = tape.scalar(0.4)
  let y = tape.add(tape.mul(x, x), tape.sin(x))
  tape.backward(y)
  assert_true(
    (tape.gradient(x) - (0.8 + @math.cos(0.4))).abs() < 0.000000000001,
  )
  tape.backward(y)
  assert_true(
    (tape.gradient(x) - (0.8 + @math.cos(0.4))).abs() < 0.000000000001,
  )
}

///|
test "disconnected singular branches do not pollute gradients" {
  let tape = @numeric.Tape::new()
  let x = tape.scalar(2)
  ignore(tape.sqrt(tape.scalar(0)))
  ignore(tape.acos(tape.scalar(1)))
  let y = tape.mul(x, x)
  tape.backward(y)
  assert_eq(tape.gradient(x), 4)
}

///|
test "atan2 gradient and population normalization" {
  let tape = @numeric.Tape::new()
  let y = tape.scalar(3)
  let x = tape.scalar(4)
  tape.backward(tape.atan2(y, x))
  assert_true((tape.gradient(y) - 0.16).abs() < 0.000000000001)
  assert_true((tape.gradient(x) + 0.12).abs() < 0.000000000001)
  let stats = @numeric.fit_normalization([[1.0, 5.0], [3.0, 5.0]], 0.1)
  assert_eq(stats.mean, [2.0, 5.0])
  assert_eq(stats.scale, [1.0, 0.1])
}

///|
test "Adam first update and independently retained optimizer snapshot" {
  let parameters = [2.0]
  let adam = @numeric.Adam::new(1, 0.01)
  let tape = @numeric.Tape::new()
  let bound = tape.vector(parameters)
  tape.backward(tape.mul(bound[0], bound[0]))
  ignore(adam.step(parameters, tape, bound, max_norm=100))
  assert_true((parameters[0] - 1.990000000025).abs() < 0.000000000001)
  let saved = adam.snapshot()
  adam.set_learning_rate(0.02)
  adam.restore(saved)
  assert_eq(adam.steps, 1)
  assert_eq(adam.learning_rate, 0.01)
}

///|
pub fn clip(value : Double, lower : Double, upper : Double) -> Double {
  @math.minimum(@math.maximum(value, lower), upper)
}

///|
pub(all) struct LearnedAnkleHead {
  nu : Int32
  indices : Array[Int32]
  lower : Array[Double]
  upper : Array[Double]
  bound : Double
  pose_rate : Bool
  mean : Array[Array[Double]]
  scale : Array[Array[Double]]
  weight : Array[Array[Double]]
} derive(Debug, ToJson, FromJson)

///|
pub fn LearnedAnkleHead::new(
  names : Array[String],
  lower : Array[Double],
  upper : Array[Double],
  bound~ : Double = 0.3,
  pose_rate~ : Bool = false,
) -> LearnedAnkleHead {
  let indices : Array[Int32] = []
  for side in ["left", "right"] {
    for axis in ["pitch", "roll"] {
      let name = side + "_ankle_" + axis + "_joint"
      let mut found = -1
      for i, n in names {
        if n == name {
          found = i
        }
      }
      guard found >= 0 else { abort("missing ankle joint") }
      indices.push(found)
    }
  }
  let dimensions = if pose_rate { 5 } else { 3 }
  {
    nu: names.length(),
    indices,
    lower: indices.map(fn(i) { lower[i] }),
    upper: indices.map(fn(i) { upper[i] }),
    bound,
    pose_rate,
    mean: Array::makei(4, fn(_) { Array::make(dimensions, 0.0) }),
    scale: Array::makei(4, fn(_) { Array::make(dimensions, 1.0) }),
    weight: Array::makei(4, fn(_) { Array::make(dimensions + 1, 0.0) }),
  }
}

///|
pub fn LearnedAnkleHead::inputs(
  self : LearnedAnkleHead,
  obs : Array[Double],
  features : Array[Double],
) -> Array[Array[Double]] {
  let gx = obs[2 * self.nu]
  let gy = obs[2 * self.nu + 1]
  let gz = obs[2 * self.nu + 2]
  let pitch = @math.atan2(gx, (gy * gy + gz * gz).sqrt())
  let roll = @math.atan2(-gy, -gz)
  Array::makei(4, fn(j) {
    let axis = j % 2
    let row = [
      features[axis],
      features[3 + axis],
      obs[self.nu + self.indices[j]],
    ]
    if self.pose_rate {
      row.push(if axis == 0 { pitch } else { roll })
      row.push(obs[2 * self.nu + 3 + (if axis == 0 { 1 } else { 0 })])
    }
    row
  })
}

///|
pub fn LearnedAnkleHead::residual(
  self : LearnedAnkleHead,
  inputs : Array[Array[Double]],
) -> Array[Double] {
  Array::makei(4, fn(j) {
    let n = inputs[j].length()
    let mut y = self.weight[j][n]
    for k in 0..<n {
      y += (inputs[j][k] - self.mean[j][k]) /
        self.scale[j][k] *
        self.weight[j][k]
    }
    y
  })
}

///|
pub fn LearnedAnkleHead::predict(
  self : LearnedAnkleHead,
  obs : Array[Double],
  goal : Array[Double],
  features : Array[Double],
) -> Array[Double] {
  let residual = self.residual(self.inputs(obs, features))
  Array::makei(4, fn(j) {
    clip(
      goal[self.indices[j]] + clip(residual[j], -self.bound, self.bound),
      self.lower[j],
      self.upper[j],
    )
  })
}

///|
/// Modified Gram-Schmidt QR, with a second orthogonalization pass. Unlike normal equations this avoids squaring the design condition number.
pub fn least_squares(
  matrix : Array[Array[Double]],
  target : Array[Double],
) -> Array[Double] {
  guard !matrix.is_empty() && matrix.length() == target.length() else {
    abort("empty or misaligned OLS")
  }
  let columns = matrix[0].length()
  guard matrix.length() >= columns else { abort("OLS design is not full rank") }
  let q : Array[Array[Double]] = []
  let r = Array::makei(columns, fn(_) { Array::make(columns, 0.0) })
  for j in 0..<columns {
    let v = matrix.map(fn(row) { row[j] })
    let initial_norm = dot(v, v).sqrt()
    for _ in 0..<2 {
      for k in 0..<j {
        let projection = dot(q[k], v)
        r[k][j] += projection
        for i in 0..<v.length() {
          v[i] -= projection * q[k][i]
        }
      }
    }
    let norm = dot(v, v).sqrt()
    guard norm > 1.0e-12 * @math.maximum(initial_norm, 1.0) else {
      abort("OLS design is not full rank")
    }
    r[j][j] = norm
    q.push(v.map(fn(x) { x / norm }))
  }
  let solution = q.map(fn(column) { dot(column, target) })
  for reverse in 0..<columns {
    let j = columns - 1 - reverse
    for k in (j + 1)..<columns {
      solution[j] -= r[j][k] * solution[k]
    }
    solution[j] /= r[j][j]
  }
  solution
}

///|
pub(all) struct FitReport {
  uncensored_points : Int32
  rank : Int32
  rmse : Double
  raw_coefficients : Array[Double]
} derive(Debug, ToJson, FromJson)

///|
pub fn LearnedAnkleHead::fit(
  self : LearnedAnkleHead,
  inputs : Array[Array[Array[Double]]],
  goals : Array[Array[Double]],
  targets : Array[Array[Double]],
  margin~ : Double = 2.0e-6,
) -> Array[FitReport] {
  let n = inputs.length()
  guard n > 0 && goals.length() == n && targets.length() == n else {
    abort("invalid training points")
  }
  let dimensions = inputs[0][0].length()
  for j in 0..<4 {
    for k in 0..<dimensions {
      let mut mean = 0.0
      for row in inputs {
        mean += row[j][k] / n.to_double()
      }
      let mut variance = 0.0
      for row in inputs {
        let d = row[j][k] - mean
        variance += d * d / n.to_double()
      }
      self.mean[j][k] = mean
      self.scale[j][k] = @math.maximum(variance.sqrt(), 1.0e-6)
    }
  }
  let reports : Array[FitReport] = []
  for j in 0..<4 {
    let matrix : Array[Array[Double]] = []
    let target : Array[Double] = []
    for i in 0..<n {
      let y = targets[i][self.indices[j]]
      let residual = y - goals[i][self.indices[j]]
      if residual.abs() < self.bound - margin &&
        y > self.lower[j] + margin &&
        y < self.upper[j] - margin {
        let row = Array::makei(dimensions, fn(k) {
          (inputs[i][j][k] - self.mean[j][k]) / self.scale[j][k]
        })
        row.push(1.0)
        matrix.push(row)
        target.push(residual)
      }
    }
    let solution = least_squares(matrix, target)
    for k in 0..<=dimensions {
      self.weight[j][k] = solution[k]
    }
    let mut squared = 0.0
    for i in 0..<matrix.length() {
      let d = dot(matrix[i], solution) - target[i]
      squared += d * d
    }
    let raw = Array::makei(dimensions, fn(k) { solution[k] / self.scale[j][k] })
    let mut bias = solution[dimensions]
    for k in 0..<dimensions {
      bias -= raw[k] * self.mean[j][k]
    }
    raw.push(bias)
    reports.push({
      uncensored_points: target.length(),
      rank: dimensions + 1,
      rmse: (squared / target.length().to_double()).sqrt(),
      raw_coefficients: raw,
    })
  }
  reports
}

///|
pub(all) struct SustainedBalanceHead {
  ankle : LearnedAnkleHead
  waist_index : Int32
  waist_lower : Double
  waist_upper : Double
  control_waist : Bool
  output_bound : Double
  fit_bound : Double
  waist_mean : Array[Double]
  waist_scale : Array[Double]
  waist_weight : Array[Double]
} derive(Debug, ToJson, FromJson)

///|
pub fn SustainedBalanceHead::new(
  names : Array[String],
  lower : Array[Double],
  upper : Array[Double],
  pose_rate~ : Bool = true,
  control_waist~ : Bool = true,
  output_bound~ : Double = 0.45,
  fit_bound~ : Double = 0.45,
) -> SustainedBalanceHead {
  let mut waist_index = -1
  for i, name in names {
    if name == "waist_pitch_joint" {
      waist_index = i
    }
  }
  guard waist_index >= 0 else { abort("missing waist pitch joint") }
  {
    ankle: LearnedAnkleHead::new(
      names,
      lower,
      upper,
      bound=fit_bound,
      pose_rate~,
    ),
    waist_index,
    waist_lower: lower[waist_index],
    waist_upper: upper[waist_index],
    control_waist,
    output_bound,
    fit_bound,
    waist_mean: [0.0, 0.0],
    waist_scale: [1.0, 1.0],
    waist_weight: [0.0, 0.0, 0.0],
  }
}

///|
pub fn SustainedBalanceHead::waist_inputs(
  self : SustainedBalanceHead,
  obs : Array[Double],
  inputs : Array[Array[Double]],
  residual : Array[Double],
) -> Array[Double] {
  let a = residual[0] -
    self.ankle.weight[0][2] / self.ankle.scale[0][2] * inputs[0][2]
  let b = residual[2] -
    self.ankle.weight[2][2] / self.ankle.scale[2][2] * inputs[2][2]
  [
    clip((a + b) / 2.0, -self.fit_bound, self.fit_bound),
    obs[self.ankle.nu + self.waist_index],
  ]
}

///|
pub fn SustainedBalanceHead::predict(
  self : SustainedBalanceHead,
  obs : Array[Double],
  goal : Array[Double],
  features : Array[Double],
) -> Array[Double] {
  let inputs = self.ankle.inputs(obs, features)
  let residual = self.ankle.residual(inputs)
  let result = Array::makei(4, fn(j) {
    clip(
      goal[self.ankle.indices[j]] +
      clip(residual[j], -self.output_bound, self.output_bound),
      self.ankle.lower[j],
      self.ankle.upper[j],
    )
  })
  if self.control_waist {
    let waist = self.waist_inputs(obs, inputs, residual)
    let correction = self.waist_weight[2] +
      (waist[0] - self.waist_mean[0]) /
      self.waist_scale[0] *
      self.waist_weight[0] +
      (waist[1] - self.waist_mean[1]) /
      self.waist_scale[1] *
      self.waist_weight[1]
    result.push(
      clip(
        goal[self.waist_index] +
        clip(correction, -self.output_bound, self.output_bound),
        self.waist_lower,
        self.waist_upper,
      ),
    )
  }
  result
}

///|
pub fn SustainedBalanceHead::fit(
  self : SustainedBalanceHead,
  observations : Array[Array[Double]],
  goals : Array[Array[Double]],
  targets : Array[Array[Double]],
  features : Array[Array[Double]],
  margin~ : Double = 2.0e-6,
) -> (Array[FitReport], FitReport) {
  let inputs = Array::makei(observations.length(), fn(i) {
    self.ankle.inputs(observations[i], features[i])
  })
  let reports = self.ankle.fit(inputs, goals, targets, margin~)
  let x = Array::makei(observations.length(), fn(i) {
    self.waist_inputs(
      observations[i],
      inputs[i],
      self.ankle.residual(inputs[i]),
    )
  })
  for k in 0..<2 {
    let mut mean = 0.0
    for row in x {
      mean += row[k] / x.length().to_double()
    }
    let mut variance = 0.0
    for row in x {
      let d = row[k] - mean
      variance += d * d / x.length().to_double()
    }
    self.waist_mean[k] = mean
    self.waist_scale[k] = @math.maximum(variance.sqrt(), 1.0e-6)
  }
  let matrix : Array[Array[Double]] = []
  let target : Array[Double] = []
  for i in 0..<x.length() {
    let y = targets[i][self.waist_index]
    let residual = y - goals[i][self.waist_index]
    if residual.abs() < self.fit_bound - margin &&
      y > self.waist_lower + margin &&
      y < self.waist_upper - margin {
      matrix.push([
        (x[i][0] - self.waist_mean[0]) / self.waist_scale[0],
        (x[i][1] - self.waist_mean[1]) / self.waist_scale[1],
        1.0,
      ])
      target.push(residual)
    }
  }
  let solution = least_squares(matrix, target)
  for i in 0..<3 {
    self.waist_weight[i] = solution[i]
  }
  let raw = [
    solution[0] / self.waist_scale[0],
    solution[1] / self.waist_scale[1],
  ]
  raw.push(
    solution[2] - raw[0] * self.waist_mean[0] - raw[1] * self.waist_mean[1],
  )
  let mut squared = 0.0
  for i in 0..<target.length() {
    let d = dot(matrix[i], solution) - target[i]
    squared += d * d
  }
  (
    reports,
    {
      uncensored_points: target.length(),
      rank: 3,
      rmse: (squared / target.length().to_double()).sqrt(),
      raw_coefficients: raw,
    },
  )
}

///|
pub(all) enum FeedbackHead {
  Learned(LearnedAnkleHead)
  Sustained(SustainedBalanceHead)
} derive(Debug, ToJson, FromJson)

///|
pub struct LearnedBalanceRunner {
  parent : (Array[Double], Array[Double]) -> Array[Double]
  head : FeedbackHead
  history : BalanceHistory
  mut last_feature : Array[Double]?
  mut last_parent : Array[Double]?
}

///|
pub fn LearnedBalanceRunner::new(
  parent : (Array[Double], Array[Double]) -> Array[Double],
  head : FeedbackHead,
  history : BalanceHistory,
) -> LearnedBalanceRunner {
  { parent, head, history, last_feature: None, last_parent: None, }
}

///|
pub fn LearnedBalanceRunner::predict(
  self : LearnedBalanceRunner,
  observation : Array[Double],
  goal : Array[Double],
) -> Array[Double] {
  let action = (self.parent)(observation, goal).copy()
  let features = self.history.observe(observation)
  self.last_feature = Some(features.copy())
  self.last_parent = Some(action.copy())
  match self.head {
    Learned(head) => {
      let corrected = head.predict(observation, goal, features)
      for j in 0..<4 {
        action[head.indices[j]] = corrected[j]
      }
    }
    Sustained(head) => {
      let corrected = head.predict(observation, goal, features)
      for j in 0..<4 {
        action[head.ankle.indices[j]] = corrected[j]
      }
      if head.control_waist {
        action[head.waist_index] = corrected[4]
      }
    }
  }
  action
}
